def is_power_of_n(x, n):
    if x < 1 or n <= 0 or (n == 1 and x != 1):
        return False
    if x == 1:
        return True  # n^0 == 1
    if n == 1:
        return x == 1
    while x % n == 0:
        x //= n
        if x == 1:
            return True
    return False

