def encode_cyclic(s: str) -> str:
    """
    Encode a string by rotating each full three‑character block left by one.
    Partial blocks (length < 3) are left unchanged.
    """
    return ''.join(
        (chunk[1:] + chunk[0]) if len(chunk) == 3 else chunk
        for chunk in _group_chunks(s)
    )


def decode_cyclic(s: str) -> str:
    """
    Decode a string that was encoded with `encode_cyclic`.
    Rotates each full three‑character block right by one.
    Partial blocks (length < 3) are left unchanged.
    """
    return ''.join(
        (chunk[-1] + chunk[:-1]) if len(chunk) == 3 else chunk
        for chunk in _group_chunks(s)
