def check_bracket_nesting(pairs):
    """
    Checks if any bracket pair contains another pair.
    Assumes pairs are given as a list of (start, end) tuples of indices.
    Returns True if there is at least one pair that strictly contains another.
    """
    # Sort by start index, then by end index descending to handle nested structures easily.
    sorted_pairs = sorted(pairs, key=lambda x: (x[0], -x[1]))

    def any_contains(others, current):
        # others: list of (start, end) tuples, current: (start, end) tuple
        # Returns True if current strictly contains any other pair in others.
        return any(s > current[0] and e < current[1] for s, e in others)

    # Use a generator to check each pair against the rest
    return any(
        any_contains(sorted_pairs[:i] + sorted_pairs[i+1:], p)
        for i, p in enumerate(sorted_pairs)
    )

